        "backtap.v3_body":       "Triple-tap and say it the way you would to a person — \"lunch 45 thousand and parking 5 thousand\" works, and so does Indonesian. DiPo listens, shows you the sentence, and turns it into a card you confirm.",
        "backtap.s1_title":      "Open Shortcuts and create a new one",
        "backtap.s1_body":       "In the Shortcuts app, go to My Shortcuts and tap + in the top right.",
        "backtap.s2_title":      "Add \"Take Screenshot\"",
        "backtap.s2_body":       "Search for Take Screenshot and add it. This has to be the first action — it captures whatever is on screen when the gesture fires.",
        "backtap.s3_title":      "Add \"Log from Screenshot\"",
        "backtap.s3_body":       "Search for DiPo and add Log from Screenshot underneath. Check that its Screenshot field shows the screenshot from step 2 — if it still says Choose, tap it and pick Screenshot, or the gesture will stop after capturing and never open DiPo.",
        "backtap.s4_title":      "Name it and save",
        "backtap.s4_body":       "Something short you will recognise later, like Log Payment.",
        "backtap.s5_title":      "Bind it to the back of your phone",
        "backtap.s5_body":       "Settings → Accessibility → Touch → Back Tap → Double Tap, then pick the shortcut you just made. Back Tap is an iOS setting, so this step cannot be done from inside DiPo.",
        "backtap.using_heading": "Using it",
        "backtap.using_body":    "Pay with QRIS, and while the receipt is still showing, double-tap the back of your phone. Works with any payment screen — e-wallet, mobile banking, or a photo of a printed receipt.\n\nBack Tap has a second slot: bind Triple Tap to DiPo's Log with Voice and you can say a transaction out loud when there is no screen to capture — cash, a warung, a friend paying you back.",
        "backtap.limits_heading":"Worth knowing",
        "backtap.limits_body":   "Nothing is saved automatically. DiPo opens a summary you can check and edit first, and when the reading was shaky it opens already editable and says so. Reading receipts is a Royal feature.",
        "backtap.open_shortcuts":"Open Shortcuts",
