        "ladder.why.debt": "Paylater, online loans and credit cards often charge 20–40% a year. No safe investment earns that, so paying them off early always wins. Cheap loans like KUR can run alongside saving.",
        "ladder.why.emergency": "Illness, a failed harvest, a repair, a slow month at the stall — an emergency fund covers these without new debt. Keep 3 months of basic costs somewhere easy to reach: savings, a deposit or gold.",
