        "quest.saving.prompt": "This month you earned %1$@. If you put %2$d%% aside as savings, how much is that?",
        "quest.saving.explain": "%1$@ × %2$d%% = %3$@. Put it aside first, as soon as the money comes in.",
        "quest.days.prompt": "You want %1$@ costing %2$@. Saving %3$@ a day, how many days until you have enough?",
        "quest.days.option": "%d days",
        "quest.days.explain": "%1$@ ÷ %2$@ = %3$d days. A little every day adds up.",
        "quest.goal.shoes": "school shoes",
        "quest.goal.uniform": "a school uniform",
        "quest.goal.bicycle": "a bicycle",
        "quest.goal.goat": "a goat",
        "quest.goal.phone": "a new phone",
        "quest.interest.prompt": "You borrow %1$@ at a flat %2$d%% a month for %3$d months. How much interest is that in total?",
        "quest.interest.explain": "%1$@ × %2$d%% × %3$d months = %4$@. In all you repay %5$@.",
        "quest.loan.prompt": "You need a loan of %@. Which one is cheaper?",
        "quest.loan.a": "%1$d%% interest a month for %2$d months",
        "quest.loan.b": "Repay %1$@ in total over %2$d months",
        "quest.loan.explain": "With the monthly rate you repay %1$@ in all; the other asks %2$@. Always compare the total you pay back.",
        "quest.scam.prompt": "%@\n\nA scam, or safe?",
        "quest.scam.0": "A WhatsApp from an unknown number: “Congratulations! You've won Rp 50 million. Transfer a Rp 500,000 admin fee first.”",
        "quest.scam.0.why": "A scam. A real prize never asks you to pay first.",
        "quest.scam.1": "A call from a “bank officer” asking for the OTP code that just arrived on your phone.",
        "quest.scam.1.why": "A scam. A bank never asks for your OTP. Hang up.",
        "quest.scam.2": "A text: “Loan paid out in 5 minutes, no requirements. Click this link.”",
        "quest.scam.2.why": "A scam. Strange links can steal your data, and real loans aren't offered by random texts.",
        "quest.scam.3": "A new number says it's an old friend who lost their phone and needs credit sent.",
        "quest.scam.3.why": "Suspicious. Call your friend's old number first to check.",
        "quest.scam.4": "A file called “Wedding Invitation.apk” sent on WhatsApp.",
        "quest.scam.4.why": "A scam. An .apk file can install an app that steals your data. Don't open it.",
        "quest.scam.5": "An investment offer: a guaranteed 30% profit every month, no risk.",
        "quest.scam.5.why": "A scam. No investment pays that much every month without risk.",
        "quest.scam.6": "A notification from your official bank app right after you paid for something.",
        "quest.scam.6.why": "Safe. It's telling you about a payment you really made.",
        "quest.scam.7": "A teller at the bank branch asks for your ID card to open an account.",
        "quest.scam.7.why": "Safe. At an official branch, ID is needed to open an account.",
        "quest.scam.8": "You call the service number printed on the back of your ATM card.",
        "quest.scam.8.why": "Safe. The number on your card is the bank's official one.",
        "quest.scam.9": "A loan from a lender registered with OJK, with the interest and fees written out clearly.",
        "quest.scam.9.why": "Safe. It's registered and the costs are clear — still work out the total you'll repay.",
        "quest.profit.prompt": "You sell %1$d %2$@ at %3$@ each. Each one costs %4$@ to make. What's your profit?",
        "quest.profit.explain": "(%1$@ − %2$@) × %3$d = %4$@. Takings of %5$@ aren't profit until the costs come off.",
        "quest.price.prompt": "One %1$@ costs %2$@ to make. For a %3$d%% profit, what should it sell for?",
        "quest.price.explain": "%1$@ + %2$d%% (%3$@) = %4$@.",
        "quest.product.fritters": "fritters",
        "quest.product.icedTea": "iced teas",
        "quest.product.cake": "cakes",
        "quest.product.porridge": "bowls of porridge",
        "quest.fact.prompt": "“%@”\n\nTrue or false?",
        "quest.fact.0": "Buying the bigger pack is always cheaper.",
        "quest.fact.0.why": "Not always. Work out the price per kilo or litre — sometimes the middle size is cheaper.",
        "quest.fact.1": "Writing a shopping list before going to the market helps you avoid overspending.",
        "quest.fact.1.why": "True. A list keeps you from buying what you didn't plan to.",
        "quest.fact.2": "A big discount always means a good deal.",
        "quest.fact.2.why": "Not necessarily. Compare with the usual price — sometimes it was raised before the discount.",
        "quest.fact.3": "A want is fine to buy once the needs are covered and the money is there.",
        "quest.fact.3.why": "True. Cover the needs first, then set a little aside for wants without borrowing.",
        "quest.fact.4": "Waiting a day before buying helps avoid impulse buys.",
        "quest.fact.4.why": "True. If you still need it tomorrow, buy it then — many wants fade overnight.",
        "quest.fact.5": "Something that's trending is a need.",
        "quest.fact.5.why": "False. A trend is a want. A need is what keeps life and work going.",
        "quest.fact.6": "An emergency fund should cover 3–6 months of needs.",
        "quest.fact.6.why": "True. It carries you through illness, a lost job or a failed harvest.",
        "quest.fact.7": "Saving is easier when you put it aside first, as soon as money comes in.",
        "quest.fact.7.why": "True. What's left for savings at the end is usually gone by then.",
        "quest.fact.8": "Saving is only for people who earn a lot.",
        "quest.fact.8.why": "False. Rp 5,000 a day is Rp 150,000 a month. What matters is doing it every day.",
        "quest.fact.9": "If the monthly interest is small, the loan must be cheap.",
        "quest.fact.9.why": "Not necessarily. 3% a month for 12 months is 36% — work out the total.",
        "quest.fact.10": "Paying instalments on time keeps your name good with the bank.",
        "quest.fact.10.why": "True. A good repayment record makes the next loan easier.",
        "quest.fact.11": "Taking a new loan to pay off an old one is a safe way out of debt.",
        "quest.fact.11.why": "False. A new loan to cover an old one piles interest on interest.",
        "quest.fact.12": "A real bank officer will never ask for your OTP or PIN.",
        "quest.fact.12.why": "True. Your OTP and PIN are only for you. Anyone asking for them is suspect.",
        "quest.fact.13": "A loan app not registered with OJK is fine as long as it pays out fast.",
        "quest.fact.13.why": "False. Illegal loan apps often charge crushing interest and fines, and spread your personal data.",
        "quest.fact.14": "An investment promising big, fixed returns with no risk is a warning sign.",
        "quest.fact.14.why": "True. Big returns always come with big risk. “Guaranteed profit” is a red flag.",
        "quest.fact.15": "Business money and personal money should be kept apart.",
        "quest.fact.15.why": "True. Kept apart, you can see whether the business really makes a profit.",
        "quest.fact.16": "High takings mean the business is surely making a profit.",
        "quest.fact.16.why": "Not necessarily. Profit is takings minus costs.",
        "quest.fact.17": "Writing down sales every day helps you set prices.",
        "quest.fact.17.why": "True. From your notes you see what sells and how much it earns.",
