        "profile.backtap":       "Ketuk untuk Catat",
        "profile.backtap_sub":   "Bayar, ketuk dua kali punggung HP, selesai",
        "backtap.hero_title":    "Bayar, ketuk dua kali, selesai",
        "backtap.hero_body":     "Saat bukti pembayaran masih di layar, ketuk dua kali punggung iPhone-mu. DiPo terbuka dengan nominal dan nama toko sudah terbaca — kamu tinggal cek lalu simpan.",
        "backtap.setup_heading": "Siapkan sekali saja",
        "backtap.voice_heading": "Atau sebut saja (ketuk tiga kali)",
        "backtap.voice_intro":   "Tidak semua pengeluaran meninggalkan layar untuk ditangkap — bayar tunai di warung, patungan, atau teman yang mengembalikan uang. Ketuk Belakang punya slot kedua untuk itu.",
        "backtap.v1_title":      "Tambahkan aksi suara DiPo",
        "backtap.v1_body":       "Di Pintasan, ketuk + lalu cari DiPo, tambahkan Log with Voice. Tidak perlu apa-apa lagi — beda dari yang tangkapan layar, aksi ini berdiri sendiri. Beri nama lalu simpan.",
        "backtap.v2_title":      "Pasang ke Ketuk Tiga Kali",
        "backtap.v2_body":       "Pengaturan → Aksesibilitas → Sentuh → Ketuk Belakang → Ketuk Tiga Kali, lalu pilih pintasan tadi. Ketuk Dua Kali tetap untuk tangkapan layar, jadi keduanya bisa dipakai.",
        "backtap.v3_title":      "Tinggal bicara",
        "backtap.v3_body":       "Ketuk tiga kali lalu ucapkan seperti bicara ke orang — \"makan siang 45rb dan parkir 5rb\" sudah cukup. DiPo mendengarkan, menampilkan kalimatnya, lalu mengubahnya jadi kartu yang tinggal kamu konfirmasi.",
        "backtap.s1_title":      "Buka Pintasan, buat yang baru",
        "backtap.s1_body":       "Di aplikasi Pintasan, masuk ke Pintasan Saya lalu ketuk + di kanan atas.",
        "backtap.s2_title":      "Tambahkan \"Ambil Tangkapan Layar\"",
        "backtap.s2_body":       "Cari Ambil Tangkapan Layar lalu tambahkan. Ini harus jadi aksi pertama — dialah yang menangkap apa pun yang sedang tampil saat gestur dijalankan.",
        "backtap.s3_title":      "Tambahkan \"Log from Screenshot\"",
        "backtap.s3_body":       "Cari DiPo lalu tambahkan Log from Screenshot di bawahnya. Pastikan kolom Screenshot-nya sudah berisi tangkapan layar dari langkah 2 — kalau masih tertulis Choose, ketuk lalu pilih Screenshot, kalau tidak gestur akan berhenti setelah memotret dan DiPo tidak terbuka.",
        "backtap.s4_title":      "Beri nama dan simpan",
        "backtap.s4_body":       "Nama pendek yang mudah kamu kenali, misalnya Catat Bayar.",
        "backtap.s5_title":      "Pasang ke punggung HP",
        "backtap.s5_body":       "Pengaturan → Aksesibilitas → Sentuh → Ketuk Belakang → Ketuk Dua Kali, lalu pilih pintasan yang barusan dibuat. Ketuk Belakang adalah pengaturan iOS, jadi langkah ini tidak bisa dilakukan dari dalam DiPo.",
        "backtap.using_heading": "Cara pakainya",
        "backtap.using_body":    "Bayar pakai QRIS, dan selagi struknya masih tampil, ketuk dua kali punggung HP. Berlaku untuk layar pembayaran apa pun — e-wallet, mobile banking, atau foto struk kertas.\n\nKetuk Belakang punya slot kedua: pasang Ketuk Tiga Kali ke Log with Voice milik DiPo, lalu kamu bisa mengucapkan transaksi saat tidak ada layar untuk difoto — bayar tunai, di warung, atau teman yang mengembalikan uang.",
        "backtap.limits_heading":"Perlu diketahui",
        "backtap.limits_body":   "Tidak ada yang tersimpan otomatis. DiPo membuka ringkasan yang bisa kamu cek dan ubah dulu, dan kalau hasil bacanya kurang yakin, langsung terbuka dalam mode ubah sambil memberi tahu. Membaca struk adalah fitur Royal.",
        "backtap.open_shortcuts":"Buka Pintasan",
