        "quest.nw.prompt": "“%@” — kebutuhan atau keinginan?",
        "quest.nw.why_need": "Kebutuhan: tanpa ini, hidup atau kerja sehari-hari jadi terganggu.",
        "quest.nw.why_want": "Keinginan: menyenangkan, tapi bisa ditunda tanpa masalah.",
