        "quest.saving.prompt": "Pemasukanmu bulan ini %1$@. Kalau %2$d%% disisihkan untuk tabungan, berapa yang ditabung?",
        "quest.saving.explain": "%1$@ × %2$d%% = %3$@. Sisihkan di awal, begitu uang masuk.",
        "quest.days.prompt": "Kamu ingin membeli %1$@ seharga %2$@. Kalau menabung %3$@ setiap hari, berapa hari sampai uangnya cukup?",
        "quest.days.option": "%d hari",
        "quest.days.explain": "%1$@ ÷ %2$@ = %3$d hari. Sedikit tiap hari, lama-lama jadi bukit.",
