        "quest.interest.explain": "%1$@ × %2$d%% × %3$d bulan = %4$@. Total yang dikembalikan %5$@.",
        "quest.loan.prompt": "Kamu butuh pinjaman %@. Mana yang lebih murah?",
        "quest.loan.a": "Bunga %1$d%% per bulan selama %2$d bulan",
        "quest.loan.b": "Kembalikan total %1$@ dalam %2$d bulan",
        "quest.loan.explain": "Dengan bunga bulanan, total kembaliannya %1$@; pilihan lain %2$@. Selalu bandingkan total yang harus dikembalikan.",
        "quest.scam.prompt": "%@\n\nPenipuan atau aman?",
        "quest.scam.0": "WA dari nomor tak dikenal: “Selamat! Kamu menang undian Rp 50 juta. Transfer biaya admin Rp 500.000 dulu.”",
        "quest.scam.0.why": "Penipuan. Hadiah asli tidak pernah meminta kamu membayar dulu.",
        "quest.scam.1": "Telepon dari “petugas bank” yang meminta kode OTP yang baru masuk ke HP-mu.",
        "quest.scam.1.why": "Penipuan. Bank tidak pernah meminta OTP. Tutup teleponnya.",
        "quest.scam.2": "SMS: “Pinjaman cair 5 menit tanpa syarat. Klik link ini.”",
        "quest.scam.2.why": "Penipuan. Link asing bisa mencuri data, dan pinjaman resmi tidak ditawarkan lewat SMS acak.",
        "quest.scam.3": "Nomor baru mengaku teman lama, minta dikirimi pulsa karena HP-nya hilang.",
        "quest.scam.3.why": "Mencurigakan. Telepon dulu nomor lama temanmu untuk memastikan.",
        "quest.scam.4": "File “Undangan Pernikahan.apk” dikirim lewat WA.",
        "quest.scam.4.why": "Penipuan. File .apk bisa memasang aplikasi pencuri data. Jangan dibuka.",
        "quest.scam.5": "Tawaran investasi: untung pasti 30% per bulan, tanpa risiko.",
        "quest.scam.5.why": "Penipuan. Tidak ada investasi yang pasti untung sebesar itu tanpa risiko.",
        "quest.scam.6": "Notifikasi transaksi dari aplikasi bank resmi, tepat setelah kamu berbelanja.",
        "quest.scam.6.why": "Aman. Itu pemberitahuan atas transaksi yang memang kamu lakukan.",
        "quest.scam.7": "Teller di kantor cabang meminta KTP saat kamu membuka rekening.",
        "quest.scam.7.why": "Aman. Di kantor resmi, KTP memang dibutuhkan untuk membuka rekening.",
        "quest.scam.8": "Kamu menelepon nomor layanan yang tertulis di balik kartu ATM-mu.",
        "quest.scam.8.why": "Aman. Nomor di balik kartu adalah nomor resmi bank.",
        "quest.scam.9": "Pinjaman dari lembaga terdaftar OJK, dengan bunga dan biaya yang tertulis jelas.",
        "quest.scam.9.why": "Aman. Terdaftar di OJK dan biayanya jelas — tetap hitung total yang harus dikembalikan.",
        "quest.profit.prompt": "Kamu menjual %1$d %2$@ seharga %3$@ per buah. Modalnya %4$@ per buah. Berapa untungnya?",
        "quest.profit.explain": "(%1$@ − %2$@) × %3$d = %4$@. Omzet %5$@ belum tentu untung — kurangi modal dulu.",
        "quest.price.prompt": "Modal satu %1$@ adalah %2$@. Kalau ingin untung %3$d%%, berapa harga jualnya?",
        "quest.price.explain": "%1$@ + %2$d%% (%3$@) = %4$@.",
