        "quest.fact.prompt": "“%@”\n\nBenar atau salah?",
        "quest.fact.0": "Membeli kemasan besar selalu lebih hemat.",
        "quest.fact.0.why": "Tidak selalu. Hitung harga per kilo atau liter — kadang kemasan sedang lebih murah.",
        "quest.fact.1": "Membuat daftar belanja sebelum ke pasar membantu menghindari belanja berlebih.",
        "quest.fact.1.why": "Benar. Daftar belanja menjaga kamu dari membeli yang tidak direncanakan.",
        "quest.fact.2": "Diskon besar berarti pasti untung.",
        "quest.fact.2.why": "Belum tentu. Bandingkan dengan harga biasanya; kadang harga dinaikkan dulu sebelum didiskon.",
        "quest.fact.3": "Keinginan boleh dibeli kalau kebutuhan sudah terpenuhi dan uangnya ada.",
        "quest.fact.3.why": "Benar. Penuhi kebutuhan dulu, lalu sisihkan sedikit untuk keinginan tanpa berutang.",
        "quest.fact.4": "Menunda pembelian sehari membantu menghindari belanja impulsif.",
        "quest.fact.4.why": "Benar. Kalau besok masih butuh, beli saja — banyak keinginan hilang setelah semalam.",
        "quest.fact.5": "Barang yang sedang tren adalah kebutuhan.",
        "quest.fact.5.why": "Salah. Tren itu keinginan. Kebutuhan adalah yang membuat hidup dan kerja tetap berjalan.",
        "quest.fact.6": "Dana darurat sebaiknya cukup untuk 3–6 bulan kebutuhan.",
        "quest.fact.6.why": "Benar. Dana darurat menolong saat sakit, kehilangan kerja, atau panen gagal.",
        "quest.fact.7": "Menabung lebih mudah kalau disisihkan di awal, begitu uang masuk.",
        "quest.fact.7.why": "Benar. Yang disisihkan di akhir biasanya sudah habis duluan.",
        "quest.fact.8": "Menabung hanya untuk orang yang penghasilannya besar.",
        "quest.fact.8.why": "Salah. Rp 5.000 sehari jadi Rp 150.000 sebulan. Yang penting rutin.",
        "quest.fact.9": "Kalau bunga per bulan kecil, total pinjamannya pasti murah.",
        "quest.fact.9.why": "Belum tentu. 3% per bulan selama 12 bulan sama dengan 36% — hitung totalnya.",
        "quest.fact.10": "Membayar cicilan tepat waktu menjaga nama baikmu di bank.",
        "quest.fact.10.why": "Benar. Riwayat bayar yang baik memudahkan pinjaman berikutnya.",
        "quest.fact.11": "Gali lubang tutup lubang adalah cara aman melunasi utang.",
        "quest.fact.11.why": "Salah. Utang baru untuk menutup utang lama membuat bunganya menumpuk.",
        "quest.fact.12": "Petugas bank resmi tidak akan pernah meminta kode OTP atau PIN-mu.",
        "quest.fact.12.why": "Benar. OTP dan PIN hanya untukmu. Siapa pun yang memintanya patut dicurigai.",
        "quest.fact.13": "Pinjol yang tidak terdaftar di OJK tetap aman kalau cairnya cepat.",
        "quest.fact.13.why": "Salah. Pinjol ilegal sering memasang bunga dan denda mencekik, dan menyebar data pribadi.",
        "quest.fact.14": "Investasi yang menjanjikan untung besar dan pasti tanpa risiko patut dicurigai.",
        "quest.fact.14.why": "Benar. Untung besar selalu datang dengan risiko besar. Janji “pasti untung” adalah tanda bahaya.",
        "quest.fact.15": "Uang usaha dan uang pribadi sebaiknya dipisah.",
        "quest.fact.15.why": "Benar. Dengan dipisah, kamu tahu usahamu benar-benar untung atau tidak.",
        "quest.fact.16": "Omzet besar berarti usaha pasti untung.",
        "quest.fact.16.why": "Belum tentu. Untung = omzet dikurangi modal dan biaya.",
        "quest.fact.17": "Mencatat penjualan setiap hari membantu menentukan harga jual.",
        "quest.fact.17.why": "Benar. Dari catatan, kamu tahu barang mana yang laku dan untungnya berapa.",
